    (30, "FN - RAZ - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de nacimiento", "Relación entre campos", "fecha_nacimiento IS NOT NULL\nAND DATEDIFF(CURRENT_DATE(), CAST(fecha_nacimiento AS DATE)) / 365.25 < 18\nAND UPPER(tipo_documento) = 'CC'", "Si DATEDIFF(YEAR, FECHA_NACIMIENTO, GETDATE()) < 18 (menor de edad): TIPO_DOCUMENTO debe estar en ('TI', 'RC', 'PS', 'CE', 'PPT'). Si TIPO_DOCUMENTO = 'CC' y edad < 18 → Error de consistencia.", 3, 1, "2026-06-01", None, "2026-06-01", "424466d5b98ec20f5f728765321bac4a", "2026-06-01"),
    (31, "GEN - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Género", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (genero IS NULL OR TRIM(UPPER(genero)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', el campo Género debe ser obligatorio. Se considera vacío si contiene NULL o cualquier valor relacionado con la ausencia del dato.", 1, 1, "2026-06-01", None, "2026-06-01", "35a8ed12e8f3eda88f5b6d6e2e2a544a", "2026-06-01"),
    (32, "GEN - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Género", "Campo", "genero IS NOT NULL\nAND UPPER(TRIM(genero)) NOT IN ('F','M','N')", "GENERO NOT IN ('F', 'M', 'N') → Valor no válido. F: Femenino, M: Masculino, N: No binario / No especifica. El campo debe validarse contra la lista de referencia del catálogo.", 2, 1, "2026-06-01", None, "2026-06-01", "86eb2b06ce4f67db9cb47876bb7c318d", "2026-06-01"),
    (33, "EPS - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "EPS actual", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (eps_actual IS NULL OR TRIM(UPPER(eps_actual)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', el campo EPS actual debe ser obligatorio. Se considera vacío si contiene NULL o cualquier valor relacionado con la ausencia del dato.", 1, 1, "2026-06-01", None, "2026-06-01", "01895fe86c57de41ebf65b9075480693", "2026-06-01"),
    (34, "EPS - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "EPS actual", "Campo", "eps_actual IS NOT NULL\nAND NOT EXISTS (\nSELECT 1 FROM referencia_eps r WHERE r.nombre_eps = eps_actual AND r.vigente = 'SI'\n)", "El valor del campo EPS debe pertenecer al listado oficial de EPS vigentes del Ministerio de Salud. Fuente: Ministerio de Salud Colombia. Valores fuera de la lista → No válido.", 2, 1, "2026-06-01", None, "2026-06-01", "b40aeb6b455f53f1f55c4f0537190a73", "2026-06-01"),
    (35, "FED - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de expedición de documento", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (fecha_expedicion_documento IS NULL OR TRIM(CAST(fecha_expedicion_documento AS STRING)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Se considera vacío si contiene: NULL, \"NULL\", \"0\", \"NE\", \"NO ESPECIFICA\", \"NO TIENE\", \"NA\", \"\", \" \".", 1, 1, "2026-06-01", None, "2026-06-01", "0e66f8c5e2e4fb55e08f797099cfde50", "2026-06-01"),
    (36, "FED - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de expedición de documento", "Campo", "fecha_expedicion_documento IS NOT NULL\nAND (\nTRY_CAST(fecha_expedicion_documento AS DATE) IS NULL\nOR CAST(fecha_expedicion_documento AS DATE) > CURRENT_DATE()\nOR CAST(fecha_expedicion_documento AS DATE) < ADD_MONTHS(CURRENT_DATE(), -101*12)\n)", "ISDATE(FECHA_EXPEDICION_DOCUMENTO) = 0 → Fecha inválida. FECHA_EXPEDICION_DOCUMENTO NOT BETWEEN DATEADD(YEAR, -101, GETDATE()) AND GETDATE() → Fuera de rango. No se admiten fechas futuras.", 2, 1, "2026-06-01", None, "2026-06-01", "f2f4a6158d0e821d43d06243f4ecca13", "2026-06-01"),
    (37, "FED - RAZ - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de expedición de documento", "Relación entre campos", "fecha_expedicion_documento IS NOT NULL\nAND fecha_nacimiento IS NOT NULL\nAND CAST(fecha_expedicion_documento AS DATE) < CAST(fecha_nacimiento AS DATE)", "FECHA_EXPEDICION_DOCUMENTO < FECHA_NACIMIENTO → Error de consistencia. La fecha de expedición debe ser posterior o igual a la fecha de nacimiento del cliente.", 3, 1, "2026-06-01", None, "2026-06-01", "4447557bd22cbe13a7338a81c9186b5d", "2026-06-01"),
    (38, "ATDP - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "ATDP (Autorización de Tratamiento de Datos Personales)", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (atdp IS NULL OR TRIM(UPPER(atdp)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', el campo ATDP debe ser obligatorio. Se considera vacío si contiene NULL o cualquier valor relacionado con la ausencia del dato.", 1, 1, "2026-06-01", None, "2026-06-01", "7a09808ffd33c4742c34e492e3cd40b0", "2026-06-01"),
    (39, "ATDP - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "ATDP (Autorización de Tratamiento de Datos Personales)", "Campo", "atdp IS NOT NULL\nAND UPPER(TRIM(atdp)) NOT IN ('SI','NO')", "ATDP NOT IN ('SI', 'NO') → Valor no válido", 2, 1, "2026-06-01", None, "2026-06-01", "0cb33f826cbb956279793fde9d85daf8", "2026-06-01"),
    (40, "FATDP - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND atdp IS NOT NULL AND TRIM(atdp) <> ''\nAND (fecha_atdp IS NULL OR TRIM(CAST(fecha_atdp AS STRING)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', la Fecha de actualización ATDP debe ser obligatoria. Si el campo ATDP es diferente de nulo, la fecha también debe estar diligenciada.", 1, 1, "2026-06-01", None, "2026-06-01", "63936d7bb784f556838db4e943b8414f", "2026-06-01"),
    (41, "FATDP - COM - 2", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP", "Relación entre campos", "(atdp IS NOT NULL AND atdp <> '' AND fecha_atdp IS NULL)\nOR (atdp IS NULL AND fecha_atdp IS NOT NULL)", "Si ATDP IS NOT NULL y ATDP <> '' entonces FECHA_ATDP debe estar diligenciada. Si ATDP IS NULL entonces FECHA_ATDP debe ser NULL.", 2, 1, "2026-06-01", None, "2026-06-01", "a6f517beba53a22f466bdb2cc3558d85", "2026-06-01"),
    (42, "FATDP - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP", "Campo", "fecha_atdp IS NOT NULL\nAND (\nTRY_CAST(fecha_atdp AS DATE) IS NULL\nOR CAST(fecha_atdp AS DATE) > CURRENT_DATE()\n)", "ISDATE(FECHA_ATDP) = 0 → Fecha inválida. FECHA_ATDP NOT BETWEEN '1800-01-01' AND GETDATE() → Fuera de rango. No se admiten fechas futuras.", 3, 1, "2026-06-01", None, "2026-06-01", "c82b852b4139420da783d7129507e5ea", "2026-06-01"),
    (43, "FATDP - RAZ - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP", "Relación entre campos", "fecha_atdp IS NOT NULL AND fecha_nacimiento IS NOT NULL\nAND CAST(fecha_atdp AS DATE) < CAST(fecha_nacimiento AS DATE)", "FECHA_ATDP no debe ser anterior a FECHA_NACIMIENTO del cliente.", 4, 1, "2026-06-01", None, "2026-06-01", "01760be523132190ca0857180e55c0aa", "2026-06-01"),
    (44, "PC - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Preferencia de contacto (Ley 2300)", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (preferencia_contacto IS NULL OR TRIM(UPPER(preferencia_contacto)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', el campo Preferencia de contacto debe ser obligatorio. Se considera vacío si contiene NULL o cualquier valor relacionado con la ausencia del dato.", 1, 1, "2026-06-01", None, "2026-06-01", "171fb74813dfb8d971e3203defed6f21", "2026-06-01"),
    (45, "PC - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Preferencia de contacto (Ley 2300)", "Campo", "preferencia_contacto IS NOT NULL\nAND UPPER(TRIM(preferencia_contacto)) NOT IN ('EMAIL','CELULAR','TELEFONO','CORREO_POSTAL','NINGUNO')", "El campo Preferencia de contacto debe pertenecer a la lista de referencia: 'EMAIL', 'CELULAR', 'TELEFONO', 'CORREO_POSTAL', 'NINGUNO'. No se permiten valores distintos a los de la lista.", 2, 1, "2026-06-01", None, "2026-06-01", "b31e04128d4694b5cf64baaa2d69f63d", "2026-06-01"),
    (46, "FMC - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha Medio de contacto", "Campo", "preferencia_contacto IS NOT NULL AND TRIM(preferencia_contacto) <> ''\nAND (fecha_medio_contacto IS NULL OR TRIM(CAST(fecha_medio_contacto AS STRING)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Si el campo Preferencia de contacto está diligenciado, la Fecha Medio de contacto debe ser obligatoria. Se considera vacío si contiene NULL o valores en blanco.", 1, 1, "2026-06-01", None, "2026-06-01", "fdc7c182e7d163cd213d9714c8ee3f0c", "2026-06-01"),
    (47, "FMC - COM - 2", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha Medio de contacto", "Relación entre campos", "preferencia_contacto IS NOT NULL AND preferencia_contacto <> ''\nAND fecha_medio_contacto IS NULL", "Si PREFERENCIA_CONTACTO IS NOT NULL y <> '' entonces FECHA_MEDIO_CONTACTO debe estar diligenciada. ", 2, 1, "2026-06-01", None, "2026-06-01", "3bba23e3ba55168b27746f166ee6108c", "2026-06-01"),
    (48, "FMC - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha Medio de contacto", "Campo", "fecha_medio_contacto IS NOT NULL\nAND (\nTRY_CAST(fecha_medio_contacto AS DATE) IS NULL\nOR CAST(fecha_medio_contacto AS DATE) > CURRENT_DATE()\n)", "ISDATE(FECHA_MEDIO_CONTACTO) = 0 → Fecha inválida. FECHA_MEDIO_CONTACTO NOT BETWEEN '1800-01-01' AND GETDATE() → Fuera de rango. No se admiten fechas futuras.", 3, 1, "2026-06-01", None, "2026-06-01", "d42d04d7d95cb443ab7369555544eaa9", "2026-06-01"),
    (49, "FMC - RAZ - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha Medio de contacto", "Relación entre campos", "fecha_medio_contacto IS NOT NULL AND fecha_nacimiento IS NOT NULL\nAND CAST(fecha_medio_contacto AS DATE) < CAST(fecha_nacimiento AS DATE)", " FECHA_MEDIO_CONTACTO no debe ser anterior a FECHA_NACIMIENTO del cliente.", 4, 1, "2026-06-01", None, "2026-06-01", "abcd1263341944ed0cb273df75d8ce82", "2026-06-01"),
    (50, "ATDPC - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "ATDP Comercial", "Campo", "UPPER(tipo_documento) <> 'NIT'\nAND (atdp_comercial IS NULL OR TRIM(UPPER(atdp_comercial)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento <> 'NIT', el campo ATDP Comercial debe estar diligenciado. Se considera vacío si contiene NULL o valores en blanco.", 1, 1, "2026-06-01", None, "2026-06-01", "2d9263f10dfa04f117a4f387e020dd6f", "2026-06-01"),
    (51, "ATDPC - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "ATDP Comercial", "Campo", "atdp_comercial IS NOT NULL\nAND UPPER(TRIM(atdp_comercial)) NOT IN ('SI','NO')", "ATDP_COMERCIAL NOT IN ('SI', 'NO') → Valor no válido. El campo debe validarse contra la lista de referencia específica del campo.", 2, 1, "2026-06-01", None, "2026-06-01", "3be870c865fc9c3ae838e13105b625a8", "2026-06-01"),
    (52, "FATDPC - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP Comercial", "Campo", "atdp_comercial IS NOT NULL AND TRIM(atdp_comercial) <> ''\nAND (fecha_atdp_comercial IS NULL OR TRIM(CAST(fecha_atdp_comercial AS STRING)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Si el campo ATDP Comercial está diligenciado, la Fecha de actualización ATDP Comercial debe ser obligatoria. Se considera vacío si contiene NULL o valores en blanco.", 1, 1, "2026-06-01", None, "2026-06-01", "2aac5379291bf8101acb60f348a2e194", "2026-06-01"),
    (53, "FATDPC - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP Comercial", "Campo", "(atdp_comercial IS NOT NULL AND atdp_comercial <> '' AND fecha_atdp_comercial IS NULL)\nOR (atdp_comercial IS NULL AND fecha_atdp_comercial IS NOT NULL)", "ISDATE(FECHA_ATDP_COMERCIAL) = 0 → Fecha inválida. FECHA_ATDP_COMERCIAL NOT BETWEEN '1800-01-01' AND GETDATE() → Fuera de rango. No se admiten fechas futuras.", 3, 1, "2026-06-01", None, "2026-06-01", "4fdf943c49f9386c84ef17a7a454360b", "2026-06-01"),
    (54, "FATDPC - COM - 2", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Fecha de actualización ATDP Comercial", "Relación entre campos", "fecha_atdp_comercial IS NOT NULL\nAND (\nTRY_CAST(fecha_atdp_comercial AS DATE) IS NULL\nOR CAST(fecha_atdp_comercial AS DATE) > CURRENT_DATE()\n)", "Si ATDP_COMERCIAL IS NOT NULL y <> '' entonces FECHA_ATDP_COMERCIAL debe estar diligenciada. Si ATDP_COMERCIAL IS NULL entonces FECHA_ATDP_COMERCIAL debe ser NULL.", 2, 1, "2026-06-01", None, "2026-06-01", "05ccdea241dad31d859f95c7b12fed73", "2026-06-01"),
    (55, "TP - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Tipo de persona", "Campo", "tipo_persona IS NULL\nOR TRIM(UPPER(tipo_persona)) IN ('NULL','NE','NO ESPECIFICA','',' ')", "Se considera como campo vacío si contiene: NULL, \"NULL\", \"NE\", \"NO ESPECIFICA\", \"\", \" \". El campo debe estar diligenciado en el 100% de los registros independientemente del canal de captura.", 1, 1, "2026-06-01", None, "2026-06-01", "752bf49911f4fa58433d9f31bb6f6198", "2026-06-01"),
    (56, "TP - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Tipo de persona", "Campo", "tipo_persona IS NOT NULL\nAND UPPER(TRIM(tipo_persona)) NOT IN ('NATURAL','JURIDICA','N','J')", "TIPO_PERSONA NOT IN ('NATURAL', 'JURIDICA') → Valor no válido. Equivalencias aceptadas en catálogo: N / NATURAL, J / JURIDICA. El campo debe validarse contra la tabla de referencia maestra del sistema.", 2, 1, "2026-06-01", None, "2026-06-01", "18897ed9dea27b2df343f3fef5ad374a", "2026-06-01"),
    (57, "TP - RAZ - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Tipo de persona", "Relación entre campos", "(UPPER(tipo_persona) IN ('JURIDICA','J') AND UPPER(tipo_documento) <> 'NIT')\nOR (UPPER(tipo_persona) IN ('NATURAL','N')  AND UPPER(tipo_documento) = 'NIT')", "Si TIPO_PERSONA = 'JURIDICA' entonces TIPO_DOCUMENTO debe ser 'NIT'. Si TIPO_PERSONA = 'NATURAL' entonces TIPO_DOCUMENTO NOT IN ('NIT').", 3, 1, "2026-06-01", None, "2026-06-01", "ba5affe8c1b735132ce57086d09a60c4", "2026-06-01"),
    (58, "EC - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Estado civil", "Campo", "UPPER(tipo_documento) = 'CC'\nAND (estado_civil IS NULL OR TRIM(UPPER(estado_civil)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento = 'CC' (mayor de edad), el campo Estado civil debe ser obligatorio. Se considera vacío si contiene: NULL, \"NULL\", \"NE\", \"NO ESPECIFICA\", \"NA\", \"\", \" \".", 1, 1, "2026-06-01", None, "2026-06-01", "b6aa2e56bb31c260e6f6950db63cc081", "2026-06-01"),
    (59, "EC - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Estado civil", "Campo", "estado_civil IS NOT NULL\nAND UPPER(TRIM(estado_civil)) NOT IN ('SOLTERO','CASADO','UNION_LIBRE','DIVORCIADO','VIUDO','SEPARADO')", "ESTADO_CIVIL NOT IN ('SOLTERO', 'CASADO', 'UNION_LIBRE', 'DIVORCIADO', 'VIUDO', 'SEPARADO') → Valor no válido. El campo debe validarse contra la lista de referencia maestra del catálogo de estado civil.", 2, 1, "2026-06-01", None, "2026-06-01", "dededd49dd5804b11f3f01df6edf31cc", "2026-06-01"),
    (60, "AE - COM - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Actividad económica", "Campo", "UPPER(tipo_documento) = 'NIT'\nAND (actividad_economica IS NULL OR TRIM(UPPER(actividad_economica)) IN (NULL, 'NULL', '0', 'NE', 'NO ESPECIFICA', 'NO TIENE', 'NA', '', ' '))", "Para registros con Tipo de documento = 'NIT' o productos de riesgo ocupacional, el campo Actividad económica debe ser obligatorio. Se considera vacío si contiene: NULL, \"NULL\", \"NE\", \"NO ESPECIFICA\", \"NA\", \"\", \" \".", 1, 1, "2026-06-01", None, "2026-06-01", "2c4f29726dd3ecd427135d234f3c914a", "2026-06-01"),
    (61, "AE - VAL - 1", "uc-axa-cli.silver.sv_sat_arl, uc-axa-cli.silver.sv_sat_beyond_health, uc-axa-cli.silver.sv_sat_pyc", "Actividad económica", "Campo", "actividad_economica IS NOT NULL\nAND NOT actividad_economica RLIKE '^[0-9]{4}$'", "El valor del campo Actividad económica debe pertenecer a la tabla de referencia CIIU Rev. 4 A.C. del DANE. Fuente: DANE Colombia. Valores fuera de la lista → No válido. El código debe ser numérico de 4 dígitos.", 2, 1, "2026-06-01", None, "2026-06-01", "2f88aa3fba07ff5d1bb39054693ea0c1", "2026-06-01"),
