df_rules = spark.createDataFrame(RAW_DATA, schema=SCHEMA)
print(f"Reglas preparadas: {df_rules.count()}")
df_rules.show(5, truncate=60)

# COMMAND ----------
# MAGIC %md
# MAGIC ## Bloque 3 — Crear tabla si no existe

def table_exists(tbl):
    try:
        spark.sql(f"DESCRIBE TABLE {tbl}")
        return True
    except Exception:
        return False

if not table_exists(TARGET):
    df_rules.limit(0).createOrReplaceTempView("_reglas_schema_ref")
    spark.sql(f"""
        CREATE TABLE {TARGET}
        USING DELTA
        TBLPROPERTIES ('delta.enableChangeDataFeed' = 'true')
        AS SELECT * FROM _reglas_schema_ref
    """)
    spark.catalog.dropTempView("_reglas_schema_ref")
    print("Tabla creada.")
else:
    print("Tabla ya existe — se usará MERGE.")

# COMMAND ----------
# MAGIC %md
# MAGIC ## Bloque 4 — MERGE (upsert por pk_regla_calidad)

df_rules.createOrReplaceTempView("_reglas_staging")

spark.sql(f"""
MERGE INTO {TARGET} AS tgt
USING _reglas_staging AS src
  ON tgt.pk_regla_calidad = src.pk_regla_calidad
WHEN MATCHED AND tgt.hash_registro <> src.hash_registro THEN
  UPDATE SET
    tgt.tabla               = src.tabla,
    tgt.atributo            = src.atributo,
    tgt.tipo_regla          = src.tipo_regla,
    tgt.regla               = src.regla,
    tgt.grupo_regla         = src.grupo_regla,
    tgt.prioridad_regla     = src.prioridad_regla,
    tgt.estado_regla        = src.estado_regla,
    tgt.fecha_ini_vigencia  = src.fecha_ini_vigencia,
    tgt.fecha_fin_vigencia  = src.fecha_fin_vigencia,
    tgt.fecha_actualizacion = src.fecha_actualizacion,
    tgt.hash_registro       = src.hash_registro,
    tgt.fecha_creacion      = src.fecha_creacion
WHEN NOT MATCHED THEN
  INSERT (sk_regla_calidad, pk_regla_calidad, tabla, atributo, tipo_regla,
          regla, grupo_regla, prioridad_regla, estado_regla,
          fecha_ini_vigencia, fecha_fin_vigencia, fecha_actualizacion,
          hash_registro, fecha_creacion)
  VALUES (src.sk_regla_calidad, src.pk_regla_calidad, src.tabla, src.atributo, src.tipo_regla,
          src.regla, src.grupo_regla, src.prioridad_regla, src.estado_regla,
          src.fecha_ini_vigencia, src.fecha_fin_vigencia, src.fecha_actualizacion,
          src.hash_registro, src.fecha_creacion)
""")

spark.catalog.dropTempView("_reglas_staging")
print("MERGE completado.")

# COMMAND ----------
# MAGIC %md
# MAGIC ## Bloque 5 — Validación post-carga

total  = spark.sql(f"SELECT COUNT(*) AS n FROM {TARGET}").collect()[0]["n"]
nullpk = spark.sql(f"SELECT COUNT(*) AS n FROM {TARGET} WHERE pk_regla_calidad IS NULL").collect()[0]["n"]
duppk  = spark.sql(f"""
    SELECT COUNT(*) AS n FROM (
        SELECT pk_regla_calidad FROM {TARGET}
        GROUP BY pk_regla_calidad HAVING COUNT(*) > 1
    )
""").collect()[0]["n"]

print("=" * 55)
print("  VALIDACIÓN POST-CARGA")
print("=" * 55)
print(f"  Registros en tabla    : {total:>5}  (esperado: 85)")
print(f"  pk nulos              : {nullpk:>5}   {'✓' if nullpk == 0 else '✗ REVISAR'}")
print(f"  pk duplicados         : {duppk:>5}   {'✓' if duppk == 0 else '✗ REVISAR'}")

print("\n  Distribución por tipo_regla:")
spark.sql(f"""
    SELECT tipo_regla, COUNT(*) AS total
    FROM {TARGET}
    GROUP BY tipo_regla ORDER BY total DESC
""").show(truncate=False)

print("  Muestra (10 filas):")
display(spark.sql(f"SELECT * FROM {TARGET} LIMIT 10"))
